import sys
from collections import defaultdict

def dfs(node, parent, depth, adj_list, depths, sizes):
    depths[node] = depth
    sizes[node] = 1
    for neighbor in adj_list[node]:
        if neighbor != parent:
            dfs(neighbor, node, depth + 1, adj_list, depths, sizes)
            sizes[node] += sizes[neighbor]

def lca(u, v, depths, parents):
    if depths[u] < depths[v]:
        u, v = v, u
    while depths[u] > depths[v]:
        u = parents[u]
    while u != v:
        u = parents[u]
        v = parents[v]
    return u

def preprocess_lca(n, adj_list):
    depths = [0] * n
    sizes = [0] * n
    parents = [-1] * n
    dfs(0, -1, 0, adj_list, depths, sizes)

    max_power = 1
    while (1 << max_power) <= n:
        max_power += 1

    lift = [[-1] * max_power for _ in range(n)]
    for i in range(n):
